import br.com.joaovictor.meuritmolite.Occurrence;import java.time.*;import java.util.*;
public class OccurrenceTest{static void check(boolean v){if(!v)throw new AssertionError();}public static void main(String[]args){LocalDate start=LocalDate.parse("2026-01-31");check(Occurrence.occurs(start,"monthly",new HashSet<>(),LocalDate.parse("2026-02-28")));check(Occurrence.occurs(start,"monthly",new HashSet<>(),LocalDate.parse("2026-03-31")));check(!Occurrence.occurs(start,"monthly",new HashSet<>(),LocalDate.parse("2026-03-30")));ZoneId z=ZoneId.of("America/Sao_Paulo");long now=LocalDateTime.parse("2026-11-12T08:00").atZone(z).toInstant().toEpochMilli();Set<Integer>days=new HashSet<>(Arrays.asList(1,4));long next=Occurrence.next(LocalDate.parse("2026-11-01"),LocalTime.of(9,0),"weekly",days,new HashSet<>(),now,0,z);check(Instant.ofEpochMilli(next).atZone(z).toLocalDateTime().equals(LocalDateTime.parse("2026-11-12T09:00")));Set<String>skip=new HashSet<>(Arrays.asList("2026-11-12"));check(Instant.ofEpochMilli(Occurrence.next(LocalDate.parse("2026-11-01"),LocalTime.of(9,0),"weekly",days,skip,now,0,z)).atZone(z).getDayOfWeek()==DayOfWeek.MONDAY);check(Occurrence.next(LocalDate.parse("2026-11-11"),LocalTime.of(9,0),"none",days,new HashSet<>(),now,0,z)<0);check(Occurrence.next(LocalDate.parse("2026-11-12"),LocalTime.of(9,0),"daily",days,new HashSet<>(),next+1000,next,z)>next);System.out.println("Native occurrence tests: passed (monthly, weekly, skipped, expired, no duplicate)");}}
